namespace Bentrix.Mcp;

/// <summary>A refusal raised, when the workbench was opened with raiseRefusals: the answer is on it.</summary>
public sealed class RefusedException : BentrixException
{
    public Answer Answer { get; }
    public RefusedException(Answer answer) : base(answer.Reason ?? answer.Outcome) => Answer = answer;
}

/// <summary>
/// What an order came to. Ok unless refused; Outcome is the venue's word; a refusal's Reason is the venue's own
/// sentence, Kind the word a program branches on, Remedy what to change and Docs the page. Raw is the whole answer.
/// </summary>
public sealed class Answer
{
    public string Outcome { get; }
    public string? Reason { get; }
    public string? Kind { get; }
    public string? Remedy { get; }
    public string? Docs { get; }
    public long? Ticket { get; }
    public long? Order { get; }
    public JsonNode? Raw { get; }
    public bool Ok => Outcome != "refused";

    public Answer(JsonNode? raw)
    {
        Raw = raw;
        JsonNode? Get(string k) => raw?[k] ?? raw?["last_answer"]?[k];
        Outcome = Get("outcome")?.GetValue<string>() ?? "sent";
        Reason = Get("reason")?.GetValue<string>();
        Kind = Get("kind")?.GetValue<string>();
        Remedy = Get("remedy")?.GetValue<string>();
        Docs = Get("docs")?.GetValue<string>();
        Ticket = Get("ticket")?.GetValue<long>();
        Order = Get("order")?.GetValue<long>();
    }

    public override string ToString() => Reason is null ? Outcome : $"{Outcome}: {Reason}";
}

/// <summary>
/// What a Bench reaches its workbench through: a tool by its name and its arguments, answered. The connection to a
/// running Bentrix is one (<see cref="Client"/>), and so is the engine in this process (<see cref="LocalDoor"/>).
/// </summary>
public interface IDoor
{
    Task<JsonNode?> Call(string name, IDictionary<string, object?>? args = null, CancellationToken ct = default);
}

/// <summary>The engine in this process as a door: <c>Bench.Open(new LocalDoor(local))</c>.</summary>
public sealed class LocalDoor : IDoor
{
    private readonly global::Bentrix.Local _local;

    public LocalDoor(global::Bentrix.Local local) => _local = local;

    public Task<JsonNode?> Call(string name, IDictionary<string, object?>? args = null, CancellationToken ct = default)
    {
        var plain = args?.Where(kv => kv.Value is not null).ToDictionary(kv => kv.Key, kv => kv.Value);
        return Task.FromResult(_local.Call(name, plain));
    }
}

/// <summary>A workbench: its orders, its book, its clock and its state, through either door.</summary>
public sealed class Bench
{
    private readonly IDoor _c;
    private readonly bool _raise;
    private List<string>? _markets;
    private bool _mounted;
    public string Uri { get; }
    public string? Name { get; }

    public Bench(IDoor client, string uri, string? name = null, bool raiseRefusals = false)
    {
        _c = client;
        Uri = uri;
        Name = name;
        _raise = raiseRefusals;
    }

    /// <summary>A workbench: the one named (its name or its address), else the selected one, else the first.</summary>
    public static async Task<Bench> Open(IDoor client, string? name = null, bool raiseRefusals = false, CancellationToken ct = default)
    {
        var state = await client.Call("get_state", null, ct);
        // A laboratory's workbenches, then a REAL account's (paper among them).
        var every = new[] { "laboratories", "accounts" }
            .SelectMany(area => state?[area]?.AsArray() ?? new JsonArray())
            .SelectMany(home => home?["benches"]?.AsArray() ?? new JsonArray())
            .Where(b => b is not null)
            .Select(b => b!)
            .ToList();
        Bench Pick(JsonNode b) => new(client, b["uri"]!.GetValue<string>(), b["name"]?.GetValue<string>(), raiseRefusals);
        if (name is not null)
        {
            var found = every.FirstOrDefault(b => b["uri"]?.GetValue<string>() == name || b["name"]?.GetValue<string>() == name);
            if (found is not null)
            {
                return Pick(found);
            }
            var names = string.Join(", ", every.Select(b => $"'{b["name"]?.GetValue<string>()}'"));
            throw new BentrixException($"no workbench is named '{name}'; there are {(names.Length > 0 ? names : "none")}");
        }
        if (every.Count == 0)
        {
            throw new BentrixException("the workspace holds no laboratory workbench");
        }
        var selected = state?["selected"]?.GetValue<string>();
        return Pick(every.FirstOrDefault(b => selected is not null && b["uri"]?.GetValue<string>() == selected) ?? every[0]);
    }

    /// <summary>The workbench's markets.</summary>
    public async Task<List<string>> Markets(CancellationToken ct = default)
    {
        if (_markets is null)
        {
            var state = await ReadUri(Uri, ct);
            _markets = (state?["markets"]?.AsArray() ?? new JsonArray())
                .Select(m => m is JsonValue v ? v.GetValue<string>() : m!["symbol"]!.GetValue<string>())
                .ToList();
        }
        return new List<string>(_markets);
    }

    // Every read through the resource_read tool: a door is anything with Call, the connection or the engine's own.
    private Task<JsonNode?> ReadUri(string uri, CancellationToken ct) =>
        _c.Call("resource_read", new Dictionary<string, object?> { ["uri"] = uri }, ct);

    // A workbench with no engine mounted (a clone, through the application) is selected - the window shows it, which is
    // how Bentrix mounts one - and waited for, at most a minute.
    private async Task Mount(CancellationToken ct)
    {
        if (_mounted)
        {
            return;
        }
        _mounted = true;
        if ((await ReadUri(Uri, ct))?["engine"]?.GetValue<string>() != "none")
        {
            return;
        }
        await _c.Call("select_bench", new Dictionary<string, object?> { ["bench"] = Uri }, ct);
        for (var i = 0; i < 600; i++)
        {
            if ((await ReadUri(Uri, ct))?["engine"]?.GetValue<string>() != "none")
            {
                return;
            }
            await Task.Delay(100, ct);
        }
    }

    private async Task<string> Symbol(string? symbol, CancellationToken ct)
    {
        if (symbol is not null)
        {
            return symbol;
        }
        var markets = await Markets(ct);
        if (markets.Count == 1)
        {
            return markets[0];
        }
        throw new BentrixException($"this workbench holds {markets.Count} markets ({string.Join(", ", markets)}): name the symbol");
    }

    private static long? TicketOf(object? t) => t switch
    {
        null => null,
        JsonNode n when n["ticket"] is JsonNode k => k.GetValue<long>(),
        long l => l,
        int i => i,
        _ => Convert.ToInt64(t),
    };

    private static long? MomentOf(object? t) => t switch
    {
        null => null,
        DateTime d => new DateTimeOffset(DateTime.SpecifyKind(d, d.Kind == DateTimeKind.Unspecified ? DateTimeKind.Utc : d.Kind)).ToUnixTimeMilliseconds(),
        DateTimeOffset o => o.ToUnixTimeMilliseconds(),
        _ => Convert.ToInt64(t),
    };

    private static JsonNode? QuoteOf(JsonNode? page, string symbol) =>
        (page?["items"]?.AsArray() ?? new JsonArray()).FirstOrDefault(q => q?["symbol"]?.GetValue<string>() == symbol)?.DeepClone();

    private Answer Answered(JsonNode? raw)
    {
        var a = new Answer(raw);
        if (!a.Ok && _raise)
        {
            throw new RefusedException(a);
        }
        return a;
    }

    private Task<JsonNode?> Read(string tail, string? after, CancellationToken ct) =>
        ReadUri($"{Uri}/{tail}" + (after is null ? "" : $"?after={System.Uri.EscapeDataString(after)}"), ct);

    private async Task<JsonArray> Stream(string tail, CancellationToken ct)
    {
        var all = new JsonArray();
        string? after = null;
        while (true)
        {
            var page = await Read(tail, after, ct);
            var items = page?["items"]?.AsArray() ?? new JsonArray();
            if (items.Count == 0)
            {
                return all;
            }
            foreach (var x in items)
            {
                all.Add(x?.DeepClone());
            }
            after = page?["next"]?.GetValue<string>();
            if (after is null)
            {
                return all;
            }
        }
    }

    /// <summary>
    /// To the next close: a workbench that has lived through no tick steps one first (a jump never invents a first
    /// quote), then a candle of the interval; the closed candle is read back from the window.
    /// </summary>
    private async Task<JsonObject?> StepTo(string interval, string symbol, CancellationToken ct)
    {
        var stood = (await ReadUri(Uri, ct))?["cursor_ms"]?.GetValue<long>();
        var q = QuoteOf(await Read("quotes", null, ct), symbol);
        if (q?["at_ms"] is null)
        {
            await _c.Call("replay_step", new Dictionary<string, object?> { ["bench"] = Uri, ["unit"] = "tick", ["n"] = 1 }, ct);
        }
        var moved = await _c.Call("replay_step", new Dictionary<string, object?> { ["bench"] = Uri, ["unit"] = "candle", ["n"] = 1, ["timeframe"] = interval }, ct);
        var now = moved?["cursor_ms"]?.GetValue<long>();
        if (now is null || now == stood)
        {
            return null;
        }
        var got = await _c.Call("bars_window", new Dictionary<string, object?> { ["bench"] = Uri, ["symbol"] = symbol, ["frames"] = new JsonArray(interval), ["limit"] = 1 }, ct);
        var rows = got?["markets"]?[symbol]?[interval]?["rows"]?.AsArray() ?? new JsonArray();
        if (rows.Count > 0 && rows[^1] is JsonArray r)
        {
            return new JsonObject { ["time"] = r[0]?.DeepClone(), ["open"] = r[1]?.DeepClone(), ["high"] = r[2]?.DeepClone(), ["low"] = r[3]?.DeepClone(), ["close"] = r[4]?.DeepClone(), ["volume"] = r[5]?.DeepClone() };
        }
        return null;
    }

    /// <summary>A market buy of lots; sl and tp as prices.</summary>
    public async Task<Answer> Buy(double lots, string? symbol = null, double? sl = null, double? tp = null, string? tag = null, long? group = null, CancellationToken ct = default)
    {
        await Mount(ct);
        var a = new Dictionary<string, object?> { ["bench"] = Uri };
        a["side"] = JsonNode.Parse("\"buy\"");
        a["volume"] = lots;
        a["symbol"] = await Symbol(symbol, ct);
        a["sl"] = sl;
        a["tp"] = tp;
        a["tag"] = tag;
        a["group"] = group;
        return Answered(await _c.Call("order_market", a, ct));
    }

