    /// <summary>The last closed candles of interval, oldest first.</summary>
    public async Task<JsonArray> Bars(string interval = "M1", long limit = 100, string? symbol = null, CancellationToken ct = default)
    {
        await Mount(ct);
        var a = new Dictionary<string, object?> { ["bench"] = Uri };
        a["timeframe"] = interval;
